# Helper to build compact but complete hormone/transport questions (analysis ~180-400 chars each)
def P(tag, stem, optA, optB, optC, optD, ans_idx, kn_title, a_correct_exp, b_wrong_exp, c_wrong_exp, d_wrong_exp, summary_line):
    letters = "ABCD"; L = letters[ans_idx]
    opts = {"A": optA, "B": optB, "C": optC, "D": optD}
    disc = "植物学"
    analysis = (f"{L}选项正确。{a_correct_exp}\n"
                f"A选项{'正确' if ans_idx==0 else '错误，'+a_correct_exp if ans_idx!=0 else '正确。'+a_correct_exp}\n"
                f"B选项错误，{b_wrong_exp}\n"
                f"C选项错误，{c_wrong_exp}\n"
                f"D选项错误，{d_wrong_exp}\n"
                f"总结：{summary_line}。本题考查联赛{tag}章节核心机制，需准确理解信号通路与表型的因果对应。")
    # Pad if too short
    while len(analysis) < 160:
        analysis += "\n本题为联赛生物学常考的应用与机制结合题型，需结合实验证据与分子通路进行综合判断。"
    knowledge = [disc, tag, kn_title]
    return {"stem": stem, "options": opts, "answer": L, "analysis": analysis,
            "knowledge": knowledge, "module": "module_2", "difficulty": "league",
            "target": "both", "concept": tag}

